target_table = {}

cdc_events = [
    {'op': 'c', 'after': {'id': 1, 'nombre': 'Alice', 'saldo': 100.0}},
    {'op': 'u', 'before': {'id': 1, 'saldo': 100.0}, 'after': {'id': 1, 'nombre': 'Alice', 'saldo': 150.0}},
    {'op': 'c', 'after': {'id': 2, 'nombre': 'Bob', 'saldo': 80.0}},
    {'op': 'd', 'before': {'id': 2, 'nombre': 'Bob', 'saldo': 80.0}}
]

for ev in cdc_events:
    op = ev['op']
    if op in {'c', 'u'}:
        rec = ev['after']
        target_table[rec['id']] = rec
    elif op == 'd':
        rec = ev['before']
        target_table.pop(rec['id'], None)

print('Registros activos en destino:', len(target_table))
print('Cliente activo 1 saldo:', target_table[1]['saldo'])
